// Any failed LendLoop run lands here, so failures are never silent.
// Replace the log with an email or Slack alert to the on-call person.
const e = $input.first().json;
const summary = {
  workflow: e.workflow?.name,
  executionId: e.execution?.id,
  url: e.execution?.url,
  failedNode: e.execution?.lastNodeExecuted,
  error: e.execution?.error?.message,
  at: new Date().toISOString(),
};
console.error('[LendLoop automation failure]', JSON.stringify(summary));
return [{ json: summary }];
